window.__log=[];let cur=null;
window.addEventListener('error',e=>window.__log.push({cur,t:'exception',m:String(e.message)}));
window.addEventListener('unhandledrejection',e=>window.__log.push({cur,t:'rejection',m:String(e.reason)}));
const btns=[...document.querySelectorAll('button')];
const res={};
for(const b of btns){const sec=b.closest('section,div')?.id||b.textContent;cur=sec;window.__log.length=0;
setTimeout(()=>b.click(),0);
await new Promise(r=>setTimeout(r,1500));
res[sec+'|'+b.textContent]=window.__log.map(x=>x.t+':'+x.m);}
JSON.stringify(res)

const btns=[...document.querySelectorAll('button')];
const res=[];
for(const [i,b] of btns.entries()){window.__log.length=0;
setTimeout(()=>b.click(),0);
await new Promise(r=>setTimeout(r,2000));
res.push(i+' '+b.parentElement.parentElement.innerText.slice(0,30).replace(/\n/g,' ')+' => '+window.__log.map(x=>x.t+':'+x.m).join(';'));}
res.join('\n')
